// Document ⇄ article, checked on the shared samples (test/mddb-samples.json):
// each sample's `page` is what ssg's own converter (internal/mddb ToPage,
// ToPages) made of the document — generated by running that Go code on the
// samples — and the editor must read the same title, slug, status, type,
// date, tags and aliases; the article text round-trips to the same meta and
// content. Then the mapping's refusals and its date reader.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { docText, goDate, matchesFilter, one, summaryOf, textDoc } from "../src/mddb-doc.ts";
import type { Meta } from "../src/mddb-client.ts";

interface Sample {
  name: string;
  doc: { key: string; lang: string; meta: Meta; contentMd: string; addedAt: number; updatedAt: number };
  text: string;
  hidden: Meta;
  page: { title: string; slug: string; status: string; type: string; date: string; tags: string[] | null; aliases: string[] | null; published: boolean };
}
const SAMPLES: Sample[] = JSON.parse(readFileSync(new URL("./mddb-samples.json", import.meta.url), "utf8"));

const instant = (s: string | null) => (s === null ? "" : new Date(goDate(s) ?? Date.parse(s)).toISOString());

for (const s of SAMPLES) {
  test(`sample: ${s.name}`, () => {
    const t = docText(s.doc.meta, s.doc.contentMd);
    assert.equal(t.text, s.text);
    assert.deepEqual(t.hidden, s.hidden);
    const back = textDoc(t.text, t.hidden);
    assert.ok(back.ok);
    const nonEmpty = Object.fromEntries(Object.entries(s.doc.meta).filter(([, v]) => v.length));
    assert.deepEqual(back.meta, nonEmpty);
    assert.equal(back.contentMd, s.doc.contentMd);
    // What the list shows agrees with what ssg builds.
    const sum = summaryOf(s.doc, null);
    assert.equal(sum.title ?? "", s.page.title);
    assert.equal(sum.slug, s.page.slug);
    assert.equal(sum.status, s.page.status);
    assert.equal(sum.type, s.page.type === "page" || s.page.type === "post" ? s.page.type : null);
    assert.equal(sum.draft, !s.page.published);
    assert.equal(instant(sum.date), s.page.date ? new Date(s.page.date).toISOString() : "");
    assert.deepEqual(back.meta.tags ?? null, s.page.tags);
    assert.deepEqual(back.meta.aliases ?? null, s.page.aliases);
  });
}

test("textDoc: no block keeps only the hidden keys; TOML, an unclosed block and nested values are refused by key", () => {
  assert.deepEqual(textDoc("Just text\n", { "a b": ["x"] }), { ok: true, meta: { "a b": ["x"] }, contentMd: "Just text\n" });
  assert.deepEqual(textDoc("+++\ntitle = \"x\"\n+++\n", {}), { ok: false, refused: [{ key: "frontmatter", reason: "toml_frontmatter" }] });
  assert.deepEqual(textDoc("---\ntitle: x\n", {}), { ok: false, refused: [{ key: "frontmatter", reason: "unclosed_frontmatter" }] });
  assert.deepEqual(textDoc("---\nauthor:\n  name: Ada\n---\n", {}), { ok: false, refused: [{ key: "author", reason: "not_flat" }] });
  assert.deepEqual(textDoc("---\ncount: 7\nflag: true\nnone:\nempty: []\n---\nB", {}), { ok: true, meta: { count: ["7"], flag: ["true"] }, contentMd: "B" });
});

test("docText: empty lists are dropped; a lone surrogate or __proto__ key is hidden, not written", () => {
  const t = docText({ e: [], __proto__x: ["a"], bad: ["\ud800"] }, "");
  assert.equal(t.text, "---\n__proto__x: a\n---\n");
  assert.deepEqual(t.hidden, { bad: ["\ud800"] });
  const proto = docText(JSON.parse('{"__proto__": ["p"]}'), "");
  assert.deepEqual([proto.text, Object.keys(proto.hidden)], ["---\n---\n", ["__proto__"]]);
});

test("goDate reads exactly ssg's four layouts", () => {
  assert.equal(goDate("2026-07-14"), Date.UTC(2026, 6, 14));
  assert.equal(goDate("2026-07-14T10:00:00"), Date.UTC(2026, 6, 14, 10));
  assert.equal(goDate("2026-07-14 10:00:00.5"), Date.UTC(2026, 6, 14, 10, 0, 0, 500));
  assert.equal(goDate("2026-07-14T10:00:00-01:30"), Date.UTC(2026, 6, 14, 11, 30));
  for (const bad of ["2026-7-14", "2026-02-30", "2026-07-14 10:00:00Z", "2026-07-14T24:00:00Z", "2026-07-14T10:60:00Z", "2026-07-14T10:00:60Z", "2026-07-14T10:00:00+24:00", "14.07.2026", ""]) {
    assert.equal(goDate(bad), null, bad);
  }
});

test("summaryOf: the source's type wins; no date and no addedAt is no date", () => {
  const s = summaryOf({ key: "k", meta: { type: ["post"] }, addedAt: 0 }, "page");
  assert.deepEqual([s.type, s.date, s.title, s.slug], ["page", null, null, "k"]);
  assert.equal(one({ a: ["x", "y"] }, "a"), null);
});

test("matchesFilter: AND between keys, OR between values; without a source type only pages and posts", () => {
  assert.equal(matchesFilter({ visibility: ["public"], type: ["page"] }, { visibility: ["public", "team"] }, null), true);
  assert.equal(matchesFilter({ visibility: ["private"], type: ["page"] }, { visibility: ["public"] }, null), false);
  assert.equal(matchesFilter({ type: ["note"] }, {}, null), false);
  assert.equal(matchesFilter({}, {}, "post"), true);
});
